import React, {
  PropsWithChildren,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useIntl } from 'react-intl';

import {
  ChevronLeftDoubleIcon,
  ChevronRightDoubleIcon,
  DragAllDirectionIcon,
} from '@dynatrace/strato-icons';

import {
  chartToolbar,
  chartToolbarArea,
  grip,
  outerContainer,
  tooltipButtons,
} from './ChartToolbarRenderer.sty.js';
import { Control } from './components/Control.js';
import { ToolbarMenu } from './components/ToolbarMenu.js';
import { ChartToolbarMenuContext } from './context/ChartToolbarMenu.context.js';
import { doesFitInBounds } from './functions/does-fit-in-bounds.js';
import { getToolbarPlacement } from './functions/get-toolbar-placement.js';
import { getToolbarWidth } from './functions/get-toolbar-width.js';
import { TOOLBAR_MESSAGES } from './messages.js';
import { Button } from '../../../../buttons/button/Button.js';
import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { Tooltip } from '../../../../overlays/tooltip/Tooltip.js';
import { Divider } from '../../../../typography/Divider.js';
import { A11yToolbarTabIndexContext } from '../../context/A11yToolbarTabIndexContext.js';
import { getDraggableBounds } from '../../functions/get-draggable-bounds.js';
import { useA11yToolbarControls } from '../../hooks/useA11yToolbarControls.js';
import { useDragElement } from '../../hooks/useDragElement.js';
import {
  A11yToolbarTabIndex,
  InternalChartToolbarConfig,
} from '../../types/toolbar.js';

/**
 * @internal
 */
export interface ChartToolbarRendererProps extends InternalChartToolbarConfig {
  /** Whether the toolbar is visible or not **/
  visible: boolean;
  /** Initial state of the A11yToolbar */
  initialA11yState: A11yToolbarTabIndex[];
  /** zIndex for the chart toolbar area */
  zIndex?: number;
  /** Callback to */
  onToggleToolbar?: (value: boolean) => void;
  /** Callback to */
  onToggleMenu?: (value: boolean) => void;
  /** Callback to */
  onMouseEnter?: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
  /** Callback to */
  onMouseLeave?: (event?: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
}

/**
 * @internal
 */
export const _ChartToolbarRenderer = (
  props: PropsWithChildren<ChartToolbarRendererProps>,
) => {
  const {
    children,
    visible,
    placement,
    collapsed = false,
    draggable = true,
    initialA11yState,
    zIndex,
    onToggleToolbar,
    onToggleMenu,
    onMouseEnter,
    onMouseLeave,
  } = props;

  const chartToolbarRef = useRef<HTMLDivElement>(null);
  const chartPlotOverlayRef = useRef<HTMLDivElement>(null);
  const [isExpanded, setIsExpanded] = useState<boolean>(!collapsed);
  const [isMenuOpen, setIsMenuOpen] = useState<boolean>(false);
  const { a11yControlsValue, setKeyEvent } =
    useA11yToolbarControls(initialA11yState);

  const maxBounds = getDraggableBounds(chartToolbarRef, chartPlotOverlayRef);
  const initialPosition = getToolbarPlacement(placement, maxBounds);

  const { isDragging, triggerDragRef } = useDragElement(
    chartToolbarRef,
    chartPlotOverlayRef,
    initialPosition,
    isExpanded,
  );

  const toolbarWidth = getToolbarWidth(children);
  const shouldCollapse =
    !doesFitInBounds(toolbarWidth, chartPlotOverlayRef) || collapsed;

  useEffect(() => {
    setIsExpanded(!shouldCollapse);
  }, [shouldCollapse]);

  const intl = useIntl();

  const tooltipText = isExpanded
    ? intl.formatMessage(TOOLBAR_MESSAGES.chartToolbarCollapse)
    : intl.formatMessage(TOOLBAR_MESSAGES.chartToolbarExpand);

  const expandHandler = () => {
    onToggleToolbar?.(isExpanded);
    setIsExpanded((isExpanded) => !isExpanded);
  };

  const handleToggleMenu = (open: boolean) => {
    onToggleMenu?.(open);
    setIsMenuOpen(open);
  };

  const prefixIcon = isExpanded ? (
    <ChevronRightDoubleIcon />
  ) : (
    <ChevronLeftDoubleIcon />
  );

  const expandCollapseButton = useMemo(
    () =>
      Array.isArray(children) && (
        <Control
          prefixIcon={prefixIcon}
          tooltipText={tooltipText}
          onClick={expandHandler}
          tabIndex={-1}
          testId="toolbar-expand-button"
        />
      ),
    [children, prefixIcon, tooltipText],
  );

  return (
    <div
      className={chartToolbarArea}
      style={{ zIndex }}
      data-testid="chart-plot-overlay-toolbar"
      ref={chartPlotOverlayRef}
    >
      <div
        className={chartToolbar}
        id="chart-toolbar"
        ref={chartToolbarRef}
        role="toolbar"
        data-testid="chart-toolbar-container"
        onKeyDown={setKeyEvent}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
      >
        <A11yToolbarTabIndexContext.Provider value={a11yControlsValue}>
          <div
            className={outerContainer({
              visible: visible || isMenuOpen || isDragging,
            })}
            data-testid="chart-toolbar-wrapper"
          >
            <ChartToolbarMenuContext.Provider value={shouldCollapse}>
              <Flex gap={2} flexDirection="row">
                {draggable && (
                  <>
                    <Tooltip
                      text={intl.formatMessage(
                        TOOLBAR_MESSAGES.chartToolbarMove,
                      )}
                      disabled={isDragging}
                    >
                      <Button
                        className={grip}
                        ref={triggerDragRef}
                        variant="default"
                        data-testid="chart-toolbar-grip"
                        tabIndex={-1}
                      >
                        <Button.Prefix>
                          {<DragAllDirectionIcon />}
                        </Button.Prefix>
                      </Button>
                    </Tooltip>
                    <Divider orientation="vertical" as="hr" />
                  </>
                )}
                <div
                  className={tooltipButtons({ isExpanded: isExpanded })}
                  data-testid="toolbar-children"
                >
                  {!shouldCollapse && children}
                </div>
                {shouldCollapse ? (
                  <ToolbarMenu onMenuOpen={handleToggleMenu}>
                    {children}
                  </ToolbarMenu>
                ) : (
                  expandCollapseButton
                )}
              </Flex>
            </ChartToolbarMenuContext.Provider>
          </div>
        </A11yToolbarTabIndexContext.Provider>
      </div>
    </div>
  );
};

_ChartToolbarRenderer['displayName'] = 'ChartToolbarRenderer';

/**
 * @internal
 */
export const ChartToolbarRenderer = Object.assign(_ChartToolbarRenderer, {
  Control,
});
